// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.decisionimport timber.log.Timberimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.DecisionCriterionimport com.roshan.persona.cognitive.model.DecisionOptionimport com.roshan.persona.cognitive.model.DecisionResultimport com.roshan.persona.cognitive.engine.ConfidenceModulatorimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Decision Maker (Module 7 v2 — Step 7.5). * * Multi-criteria decision support with transparent trade-offs. * * ## Flow (per strategy v2 §"DecisionMaker") * * ``` * 1. CriteriaAnalyzer.extractCriteria(query) → [price, camera, battery, ...] * 2. CriteriaAnalyzer.scoreOptions(options, criteria) → scores per option * 3. PreferenceAligner.align(criteria, userPrefs) → adjusted weights * 4. Recalculate overall scores with adjusted weights * 5. RiskAssessor.assessRisks(options) → risks per option * 6. Rank options → pick best * 7. Generate rationale ("I recommend X because...") * 8. ConfidenceModulator wraps recommendation * 9. Return DecisionResult * ``` * * ## Q3: Recommend with caveat * * Per Q3 decision: NOUS recommends one option but with explicit caveat: * "I lean toward Android, but iPhone is better if camera is your priority." * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§DecisionMaker</a> */class DecisionMaker(    private val criteriaAnalyzer: CriteriaAnalyzer,    private val riskAssessor: RiskAssessor,    private val preferenceAligner: PreferenceAligner,    private val confidenceModulator: ConfidenceModulator,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Make a multi-criteria decision.     *     * @param query the user's decision query ("iPhone vs Android").     * @param optionNames the options to compare (e.g., ["iPhone 15", "Samsung S24"]).     * @param userPreferences user preferences from Memory (e.g., ["budget-conscious"]).     * @param personaId the active persona ID (for ConfidenceModulator styling).     * @return a [DecisionResult] with recommendation + rationale + criteria.     */    suspend fun decide(        query: String,        optionNames: List<String>,        userPreferences: List<String> = emptyList(),        personaId: String = "default",    ): DecisionResult? = withContext(dispatcher) {        if (optionNames.size < config.minDecisionOptions) {            Timber.tag(TAG).w("Need at least ${config.minDecisionOptions} options, got ${optionNames.size}")            return@withContext null        }        val limitedOptions = optionNames.take(config.maxDecisionOptions)        Timber.tag(TAG).d("Deciding: query='$query', options=$limitedOptions, prefs=$userPreferences")        // 1. Extract criteria.        var criteria = criteriaAnalyzer.extractCriteria(query)        // 2. Align with user preferences.        if (userPreferences.isNotEmpty()) {            val alignment = preferenceAligner.align(criteria, userPreferences)            criteria = alignment.adjustedCriteria        }        // 3. Score options.        val rawScores = criteriaAnalyzer.scoreOptions(limitedOptions, criteria)        // 4. Build DecisionOption objects with overall scores.        val options = limitedOptions.map { name ->            val scores = rawScores[name] ?: emptyMap()            val overall = criteriaAnalyzer.calculateOverallScore(scores, criteria)            DecisionOption(                name = name,                scores = scores,                overallScore = overall,            )        }        // 5. Assess risks.        val riskMap = riskAssessor.assessRisks(options)        // **FIX (audit Task ID: audit-m8-cognitive P1)**: Previously, risks        // were attached as metadata but `overallScore` was computed BEFORE        // risk assessment and never adjusted. Now we apply a risk penalty:        //   - HIGH risk → score *= 0.7 (30% penalty)        //   - MEDIUM risk → score *= 0.85 (15% penalty)        //   - LOW risk → score *= 0.95 (5% penalty — minor caution)        // Then re-sort so the recommendation reflects risk-adjusted ranking.        val optionsWithRisks = options.map { opt ->            val assessment = riskMap[opt.name]            val penalty = when (assessment?.level) {                RiskLevel.HIGH -> 0.7f                RiskLevel.MEDIUM -> 0.85f                RiskLevel.LOW -> 0.95f                null -> 1.0f            }            val adjustedScore = (opt.overallScore * penalty).coerceIn(0f, 1f)            opt.copy(                overallScore = adjustedScore,                risks = assessment?.risks ?: emptyList(),            )        }        // 6. Rank + pick best (using risk-adjusted scores).        val sorted = optionsWithRisks.sortedByDescending { it.overallScore }        val recommendation = sorted.first()        // 7. Generate rationale (Q3: recommend with caveat).        val rationale = generateRationale(recommendation, sorted, criteria, userPreferences)        // 8. Calculate confidence.        val confidence = calculateConfidence(sorted)        // 9. Modulate recommendation tone.        val modulatedRationale = confidenceModulator.modulate(confidence, rationale, personaId)        DecisionResult(            options = sorted,            recommendation = recommendation,            rationale = modulatedRationale,            criteria = criteria,            userPreferencesApplied = userPreferences,            confidence = confidence,        )    }    /**     * Generate a transparent rationale (Q3: recommend with caveat).     *     * "I lean toward X because [reasons]. However, Y is better if [priority]."     */    internal fun generateRationale(        recommendation: DecisionOption,        allOptions: List<DecisionOption>,        criteria: List<DecisionCriterion>,        userPreferences: List<String>,    ): String {        val parts = mutableListOf<String>()        // Main recommendation.        val topCriterion = recommendation.scores.maxByOrNull { it.value }        parts.add("I lean toward ${recommendation.name}")        // Why — top scoring criteria.        if (topCriterion != null) {            parts.add("because it scores well on ${topCriterion.key}")        }        // User preferences applied.        if (userPreferences.isNotEmpty()) {            parts.add("which aligns with your preference for ${userPreferences.joinToString()}")        }        // Caveat — where the second-best option wins.        if (allOptions.size >= 2) {            val second = allOptions[1]            val secondBest = second.scores.maxByOrNull { it.value }            val recoWorst = recommendation.scores.minByOrNull { it.value }            if (secondBest != null && recoWorst != null && secondBest.value > recoWorst.value) {                parts.add("However, ${second.name} is better if ${secondBest.key} is your priority")            }        }        return parts.joinToString(". ") + "."    }    /**     * Calculate confidence based on score separation.     *     * - Large gap between #1 and #2 → high confidence.     * - Close scores → lower confidence.     */    internal fun calculateConfidence(sorted: List<DecisionOption>): Float {        if (sorted.size < 2) return 0.8f        val gap = sorted[0].overallScore - sorted[1].overallScore        // Map gap (0.0-1.0) to confidence (0.5-0.95).        return (0.5f + gap * 0.45f).coerceIn(0.5f, 0.95f)    }    private companion object {        private const val TAG = "DecisionMaker"    }}

